document.addEventListener('DOMContentLoaded', () => {
    // Event listener for creating a new note
    const createNoteButton = document.getElementById('create-note');
    if (createNoteButton) {
        createNoteButton.addEventListener('click', () => {
            const noteTitle = prompt('Enter the title of the note:');
            if (noteTitle) {
                // Send the new note to the backend
                fetch('/api/notes', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({ title: noteTitle }),
                })
                .then(response => response.json())
                .then(data => {
                    if (data.success) {
                        alert('Note created successfully!');
                        location.reload(); // Reload the page to show the new note
                    } else {
                        alert('Error creating note: ' + data.message);
                    }
                })
                .catch(error => console.error('Error:', error));
            }
        });
    }

    // Event listener for searching notes
    const searchInput = document.getElementById('search-notes');
    if (searchInput) {
        searchInput.addEventListener('input', () => {
            const query = searchInput.value.toLowerCase();
            const noteElements = document.querySelectorAll('.note');

            noteElements.forEach(note => {
                const title = note.querySelector('.note-title').textContent.toLowerCase();
                if (title.includes(query)) {
                    note.style.display = '';
                } else {
                    note.style.display = 'none';
                }
            });
        });
    }
});

from flask import Blueprint, render_template, request, redirect, url_for, flash
from app.database import db
from app.models.problem import Problem

problem_bp = Blueprint('problem', __name__)

@problem_bp.route('/problems', methods=['GET'])
def list_problems():
    """
    Display a list of all problems.
    """
    problems = Problem.query.all()
    return render_template('templates/problem.html', problems=problems)

@problem_bp.route('/problems/<int:problem_id>', methods=['GET'])
def view_problem(problem_id):
    """
    View a single problem by ID.
    """
    problem = Problem.query.get(problem_id)
    if not problem:
        flash("Problem not found.", "error")
        return redirect(url_for('problem.list_problems'))
    return render_template('templates/problem.html', problem=problem)

@problem_bp.route('/problems/new', methods=['GET', 'POST'])
def create_problem():
    """
    Create a new problem.
    """
    if request.method == 'POST':
        title = request.form.get('title')
        description = request.form.get('description')

        if not title or not description:
            flash("Title and description are required.", "error")
            return redirect(url_for('problem.create_problem'))

        new_problem = Problem(title=title, description=description)
        db.session.add(new_problem)
        db.session.commit()

        flash("Problem created successfully.", "success")
        return redirect(url_for('problem.list_problems'))

    return render_template('templates/submit.html')

@problem_bp.route('/problems/<int:problem_id>/edit', methods=['GET', 'POST'])
def edit_problem(problem_id):
    """
    Edit an existing problem.
    """
    problem = Problem.query.get(problem_id)
    if not problem:
        flash("Problem not found.", "error")
        return redirect(url_for('problem.list_problems'))

    if request.method == 'POST':
        title = request.form.get('title')
        description = request.form.get('description')

        if not title or not description:
            flash("Title and description are required.", "error")
            return redirect(url_for('problem.edit_problem', problem_id=problem_id))

        problem.title = title
        problem.description = description
        db.session.commit()

        flash("Problem updated successfully.", "success")
        return redirect(url_for('problem.view_problem', problem_id=problem_id))

    return render_template('templates/submit.html', problem=problem)

@problem_bp.route('/problems/<int:problem_id>/delete', methods=['POST'])
def delete_problem(problem_id):
    """
    Delete a problem by ID.
    """
    problem = Problem.query.get(problem_id)
    if not problem:
        flash("Problem not found.", "error")
        return redirect(url_for('problem.list_problems'))

    db.session.delete(problem)
    db.session.commit()

    flash("Problem deleted successfully.", "success")
    return redirect(url_for('problem.list_problems'))

from flask import Blueprint, request, jsonify
from app.database import db
from app.models.user import User

user_bp = Blueprint('user', __name__)

@user_bp.route('/users', methods=['GET'])
def list_users():
    """Retrieve a list of all users."""
    users = User.query.all()
    return jsonify([user.to_dict() for user in users])

@user_bp.route('/users/<int:user_id>', methods=['GET'])
def view_user(user_id):
    """Retrieve details of a specific user by ID."""
    user = User.query.get(user_id)
    if user:
        return jsonify(user.to_dict())
    else:
        return jsonify({'error': 'User not found'}), 404

@user_bp.route('/users', methods=['POST'])
def create_user():
    """Create a new user."""
    data = request.json
    if not data or not all(k in data for k in ('username', 'email')):
        return jsonify({'error': 'Invalid data'}), 400

    new_user = User(username=data['username'], email=data['email'])
    db.session.add(new_user)
    db.session.commit()
    return jsonify(new_user.to_dict()), 201

@user_bp.route('/users/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    """Update an existing user's details."""
    user = User.query.get(user_id)
    if not user:
        return jsonify({'error': 'User not found'}), 404

    data = request.json
    if 'username' in data:
        user.username = data['username']
    if 'email' in data:
        user.email = data['email']

    db.session.commit()
    return jsonify(user.to_dict())

@user_bp.route('/users/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    """Delete a user by ID."""
    user = User.query.get(user_id)
    if not user:
        return jsonify({'error': 'User not found'}), 404

    db.session.delete(user)
    db.session.commit()
    return jsonify({'message': 'User deleted successfully'})

from flask import Blueprint, request, jsonify, render_template, redirect, url_for
from app.database import db
from app.models.solution import Solution
from app.models.problem import Problem
from app.models.user import User

solution_bp = Blueprint('solution', __name__)

@solution_bp.route('/solutions', methods=['GET'])
def list_solutions():
    """List all solutions."""
    solutions = Solution.query.all()
    return jsonify([{
        'id': solution.id,
        'content': solution.content,
        'problem_id': solution.problem_id,
        'user_id': solution.user_id,
        'created_at': solution.created_at,
        'updated_at': solution.updated_at
    } for solution in solutions])

@solution_bp.route('/solutions/<int:solution_id>', methods=['GET'])
def view_solution(solution_id):
    """View a single solution by ID."""
    solution = Solution.query.get_or_404(solution_id)
    return jsonify({
        'id': solution.id,
        'content': solution.content,
        'problem_id': solution.problem_id,
        'user_id': solution.user_id,
        'created_at': solution.created_at,
        'updated_at': solution.updated_at
    })

@solution_bp.route('/solutions/new', methods=['GET', 'POST'])
def create_solution():
    """Create a new solution."""
    if request.method == 'POST':
        data = request.json
        content = data.get('content')
        problem_id = data.get('problem_id')
        user_id = data.get('user_id')

        if not content or not problem_id or not user_id:
            return jsonify({'error': 'Missing fields'}), 400

        # Validate problem and user existence
        problem = Problem.query.get(problem_id)
        if not problem:
            return jsonify({'error': 'Problem not found'}), 404

        user = User.query.get(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404

        new_solution = Solution(content=content, problem_id=problem_id, user_id=user_id)
        db.session.add(new_solution)
        db.session.commit()
        return jsonify({'message': 'Solution created successfully', 'id': new_solution.id}), 201

    return render_template('submit.html')

@solution_bp.route('/solutions/<int:solution_id>/edit', methods=['GET', 'POST'])
def edit_solution(solution_id):
    """Edit an existing solution."""
    solution = Solution.query.get_or_404(solution_id)

    if request.method == 'POST':
        data = request.json
        content = data.get('content')

        if not content:
            return jsonify({'error': 'Content is required'}), 400

        solution.content = content
        db.session.commit()
        return jsonify({'message': 'Solution updated successfully'})

    return render_template('submit.html', solution=solution)

@solution_bp.route('/solutions/<int:solution_id>/delete', methods=['POST'])
def delete_solution(solution_id):
    """Delete a solution."""
    solution = Solution.query.get_or_404(solution_id)
    db.session.delete(solution)
    db.session.commit()
    return jsonify({'message': 'Solution deleted successfully'})
